import { useState } from "react";
import { Image, StyleSheet, Text, View } from "react-native";
import type { ImageStyle, StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export type AvatarSize = "sm" | "md" | "lg" | "xl";

export interface AvatarProps extends ViewProps {
  name: string;
  src?: string;
  size?: AvatarSize;
  status?: "online" | "offline";
  /** Extend the inner, named parts of the avatar: image, fallback or status. The React Native counterpart of `classNames`. */
  styles?: {
    image?: StyleProp<ImageStyle>;
    fallback?: StyleProp<TextStyle>;
    status?: StyleProp<ViewStyle>;
  };
}

const dimension: Record<AvatarSize, number> = { sm: 28, md: 36, lg: 48, xl: 88 };
const fontSize: Record<AvatarSize, number> = { sm: 10, md: metrics.text.xs, lg: metrics.text.sm, xl: 22 };

export function Avatar({ name, src, size = "md", status, style, styles: parts, ...props }: AvatarProps) {
  const tokens = useTokens();
  const [failed, setFailed] = useState<string>();
  const initials = name.trim().split(/\s+/).slice(0, 2).map((part) => part[0]?.toUpperCase()).join("");
  const box = dimension[size];
  const showImage = Boolean(src) && failed !== src;

  return (
    <View
      {...props}
      accessible
      accessibilityRole="image"
      accessibilityLabel={`${name}${status ? `, ${status}` : ""}`}
      style={[
        local.root,
        { width: box, height: box, borderRadius: metrics.radiusPill, borderColor: tokens.border, backgroundColor: tokens.surfaceMuted },
        style,
      ]}
    >
      {showImage ? (
        <Image alt="" source={{ uri: src }} onError={() => setFailed(src)} style={[local.image, parts?.image]} />
      ) : (
        <Text style={[{ color: tokens.foreground, fontSize: fontSize[size], fontWeight: "500" }, parts?.fallback]}>{initials}</Text>
      )}
      {status ? (
        <View
          style={[
            local.status,
            { backgroundColor: status === "online" ? tokens.success : tokens.textMuted, borderColor: tokens.background },
            parts?.status,
          ]}
        />
      ) : null}
    </View>
  );
}

const local = StyleSheet.create({
  root: { alignItems: "center", justifyContent: "center", borderWidth: 1, overflow: "visible" },
  image: { ...StyleSheet.absoluteFillObject, borderRadius: metrics.radiusPill },
  status: { position: "absolute", right: 0, bottom: 0, width: 10, height: 10, borderRadius: 5, borderWidth: 2 },
});

export default Avatar;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
